    {"symbol": "🛡️", "tooltip": "Pre-deployment gates are like a castle wall, they assume the threat stays outside while the real danger is already inside."},
    {"symbol": "⚖️", "tooltip": "Judicial discovery is like an audit, it uncovers the hidden flaws that developers refuse to disclose."}
  ],
  "claim_sketches": [
    {"claim": "Pre-deployment gates function as a static filter for a dynamic, evolving system, failing to account for the reality that 33 percent of enterprise software applications will include agentic AI by 2028.", "targets": ["AN-36"]},
    {"claim": "Insurance pools function as legal fictions that shield corporate decision-makers from true accountability.", "targets": ["AN-34"]},
    {"claim": "We must transition from reactive negligence-based frameworks to a regime of strict liability for frontier AI.", "targets": []},
    {"claim": "Judicial discovery is the necessary sensor for an immune system model, forcing transparency that corporations currently withhold.", "targets": []}
  ],
  "key_assumptions": [
    {"assumption": "The legal system can effectively pivot to a strict liability framework for AI without stifling technological progress.", "if_wrong": "If strict liability is unworkable, we must find a different mechanism for forcing transparency, perhaps through mandatory real-time logging of model outputs."},
